import { join } from "node:path";
import { chromium, devices } from "playwright";
import { routeAccessHeaders } from "../npm-scripts/env.mjs";

const OUT = join(process.env.HOME, "development/.tmp/stallion-colours");
const BASE = "https://stallion.matthijs-f49.workers.dev";
const MIX = "#8e2de2";
const errors = [];
const browser = await chromium.launch({ headless: true });

const setup = async (name, options) => {
  const context = await browser.newContext({ colorScheme: "light", ...options });
  await routeAccessHeaders(context, BASE);
  const page = await context.newPage();
  page.on("console", (m) => m.type() === "error" && errors.push(`${name}: ${m.text()}`));
  page.on("pageerror", (e) => errors.push(`${name}: ${e.message}`));
  await page.goto(`${BASE}/b/colours-${name}-${Date.now()}`, { waitUntil: "load" });
  await page.locator("canvas.surface").waitFor({ state: "visible", timeout: 15000 });
  await page.waitForTimeout(800);
  return { context, page };
};

const face = (page) => page.getByRole("button", { name: /^Colours, now #/ });
const dialog = (page) => page.getByRole("dialog", { name: "Colours" });
const inViewport = async (page, name) => {
  const box = await dialog(page).boundingBox();
  const vp = page.viewportSize();
  const ok = box && box.x >= 0 && box.y >= 0 && box.x + box.width <= vp.width && box.y + box.height <= vp.height;
  console.log(`${name}: popover ${JSON.stringify(box)} in ${vp.width}x${vp.height} ${ok ? "inside" : "OUTSIDE"}`);
};

for (const [name, options, touch] of [
  ["phone", devices["Pixel 7"], true],
  ["tablet", devices["Galaxy Tab S9"], true],
  ["desktop", { viewport: { width: 1440, height: 789 } }, false],
]) {
  const { context, page } = await setup(name, options);
  const tap = (locator) => (touch ? locator.tap() : locator.click());
  await page.screenshot({ path: join(OUT, `${name}-closed.png`) });
  await tap(face(page));
  await dialog(page).waitFor({ state: "visible" });
  await page.waitForTimeout(200);
  await inViewport(page, name);
  await page.screenshot({ path: join(OUT, `${name}-open.png`) });
  await page.keyboard.press("Escape");
  if (name !== "desktop") {
    const more = page.getByRole("button", { name: "More tools" });
    await tap(more);
    await page.screenshot({ path: join(OUT, `${name}-expanded-closed.png`) });
    await tap(face(page));
    await page.waitForTimeout(200);
    await inViewport(page, `${name} expanded`);
    await page.screenshot({ path: join(OUT, `${name}-expanded-open.png`) });
    await page.keyboard.press("Escape");
  }
  await tap(page.locator("[data-toolbar-flip]"));
  await page.waitForTimeout(300);
  await tap(face(page));
  await page.waitForTimeout(200);
  await inViewport(page, `${name} palette`);
  await page.screenshot({ path: join(OUT, `${name}-palette-open.png`) });
  await page.keyboard.press("Escape");
  await tap(page.locator("[data-toolbar-flip]"));
  await page.waitForTimeout(300);
  if (name === "desktop") {
    await tap(face(page));
    await tap(dialog(page).getByRole("button", { name: "Empty slot 1" }));
    await dialog(page).getByLabel("Mix a colour").fill(MIX);
    await page.waitForTimeout(200);
    await page.screenshot({ path: join(OUT, "slot-tracking-mix.png") });
    await page.keyboard.press("Escape");
    await page.mouse.move(500, 400);
    await page.mouse.down();
    for (let i = 1; i <= 30; i++) await page.mouse.move(500 + i * 15, 400 + Math.sin(i / 4) * 80);
    await page.mouse.up();
    await page.waitForTimeout(1500);
    await page.reload({ waitUntil: "load" });
    await page.locator("canvas.surface").waitFor({ state: "visible" });
    await page.waitForTimeout(1500);
    await page.screenshot({ path: join(OUT, "stroke-custom-after-reload.png") });
    await tap(face(page));
    await page.waitForTimeout(200);
    console.log("slot after reload:", await dialog(page).getByRole("button", { name: `Slot 1, ${MIX}`, exact: true }).isVisible());
    await page.screenshot({ path: join(OUT, "slot-after-reload.png") });
  }
  await context.close();
}
await browser.close();
console.log(errors.length ? `console errors:\n${errors.join("\n")}` : "zero console errors");
EOF
