  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--panel);
  color: var(--ink);
  font:
    14px / 1 ui-monospace,
    monospace;
}

.hex-field[aria-invalid="true"] {
  border-color: #e5484d;
}

.toolbar[data-layout="Palette"] .hex-field {
  grid-column: 1 / -1;
