mkdir -p ~/development/.tmp/stallion-colours/v2 && cat > ~/development/stallion-worktrees/colour-inline/.tmp-shots.mjs <<'EOF'
import { join } from "node:path";
import { chromium, devices } from "playwright";
import { routeAccessHeaders } from "./npm-scripts/env.mjs";

const OUT = join(process.env.HOME, "development/.tmp/stallion-colours/v2");
const BASE = "https://stallion.matthijs-f49.workers.dev";
const MIX = "#8e2de2";
const errors = [];
const browser = await chromium.launch({ headless: true });

const fits = async (page, name) => {
  const box = await page.locator(".toolbar").boundingBox();
  const vp = page.viewportSize();
  const over = await page.evaluate(() => document.documentElement.scrollWidth > innerWidth);
  const ok = box.x >= 0 && box.x + box.width <= vp.width && box.y + box.height <= vp.height && !over;
  console.log(`${name}: toolbar ${Math.round(box.width)}x${Math.round(box.height)} in ${vp.width}x${vp.height} ${ok ? "inside" : "OUTSIDE"}`);
};

for (const [name, options, touch] of [
  ["phone", devices["Pixel 7"], true],
  ["phone-390", { ...devices["Pixel 7"], viewport: { width: 390, height: 844 } }, true],
  ["tablet", devices["Galaxy Tab S9"], true],
  ["desktop", { viewport: { width: 1440, height: 789 } }, false],
  ["desktop-960", { viewport: { width: 960, height: 700 } }, false],
]) {
  const context = await browser.newContext({ colorScheme: "light", ...options });
  await routeAccessHeaders(context, BASE);
  const page = await context.newPage();
  page.on("console", (m) => m.type() === "error" && errors.push(`${name}: ${m.text()}`));
  page.on("pageerror", (e) => errors.push(`${name}: ${e.message}`));
  await page.goto(`${BASE}/b/colours2-${name}-${Date.now()}`, { waitUntil: "load" });
  await page.locator("canvas.surface").waitFor({ state: "visible", timeout: 15000 });
  await page.waitForTimeout(800);
  const tap = (l) => (touch ? l.tap() : l.click());
  await page.screenshot({ path: join(OUT, `${name}-closed.png`) });
  await fits(page, `${name} closed`);
  const more = page.getByRole("button", { name: "More tools" });
  if (await more.isVisible()) {
    await tap(more);
    await page.waitForTimeout(300);
    await page.screenshot({ path: join(OUT, `${name}-expanded.png`) });
    await fits(page, `${name} expanded`);
  }
  await tap(page.locator("[data-toolbar-flip]"));
  await page.waitForTimeout(500);
  await page.screenshot({ path: join(OUT, `${name}-palette.png`) });
  await fits(page, `${name} palette`);
  if (name === "desktop") {
    const palette = page.locator(".toolbar");
    await tap(palette.getByRole("button", { name: "Empty slot 1" }));
    await palette.getByLabel(/^Mix a colour/).fill(MIX);
    await page.waitForTimeout(300);
    await page.screenshot({ path: join(OUT, "slot-tracking-mix.png") });
    await page.mouse.move(600, 400);
    await page.mouse.down();
    for (let i = 1; i <= 30; i++) await page.mouse.move(600 + i * 15, 400 + Math.sin(i / 4) * 80);
    await page.mouse.up();
    await page.waitForTimeout(1500);
    await page.reload({ waitUntil: "load" });
    await page.locator("canvas.surface").waitFor({ state: "visible" });
    await page.waitForTimeout(1500);
    console.log("slot after reload:", await palette.getByRole("button", { name: `Slot 1, ${MIX}`, exact: true }).isVisible());
    await page.screenshot({ path: join(OUT, "stroke-custom-after-reload.png") });
  }
  await context.close();
}
await browser.close();
console.log(errors.length ? `console errors:\n${errors.join("\n")}` : "zero console errors");
EOF
cd ~/development/stallion-worktrees/colour-inline && cap node .tmp-shots.mjs 2>&1 | tail -20

